quests[8896] = { id = 8896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dwarven Spy", description = "Are you sure you found these notes on a Night Elf, then?  Most of them are written in the Dwarven...\n\nProspector Anvilward!  He was sent here from Ironforge on a diplomatic mission.  I should've known his interest in our Arcane Sanctums was a bit excessive.  {name}, find the dwarf in the North Sanctum and take care of him.  Oh, and be discrete about it.", objectives = "Find and kill Prospector Anvilward in the North Sanctum and report back to Aeldon Sunbrand in Eversong Woods.Are you sure you found these notes on a Night Elf, then?  Most of them are written in the Dwarven...\n\nProspector Anvilward!  He was sent here from Ironforge on a diplomatic mission. I should've known his interest in our Arcane Sanctums was a bit excessive. {name}, find the dwarf in the North Sanctum and take care of him. Oh, and be discrete about it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8897] = { id = 8897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Colara,", description = "I've got to keep watch here at the gate, but I'm always worrying about my sweetheart, Colara. I only get to see her for a few hours, if I'm lucky, and well, just look at me. I've got a minor officer's pay and I could be called to the front any day now.\n\nWould she just forget about me? There are a lot of men in the city. A lot of rich ones.\n\nAnyways, I've scribbled some things down... nothing much, but if you could take it to her for me, that'd be great.", objectives = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8898] = { id = 8898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Colara,", description = "I met a lass in Stormwind when I was last there on the bank's business. She stole my heart away. Now, I can't stop thinking about her! I'd like to send her this message - I've rewritten it twelve times!\n\nThe mail is so full now, and I want to make sure it gets there.\n\nIf you're heading that way, could you help me?", objectives = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8899] = { id = 8899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Colara,", description = "How to describe her beauty? Thousands of years of words and I am at a loss.\n\nThese mortals confound the mind and leave us babbling fools.\n\nI've stared at these words too long. No more eloquent meaning can I squeeze from them. No, she must have it now, or some other suitor will surely steal her eye.", objectives = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8900] = { id = 8900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Elenia,", description = "She was so sad. I could see that, once I saw past her state. I mean, she seemed sad - wouldn't you?\n\nBut after talking to her, there was a connection. I didn't think anyone could understand what I was thinking, but she could.\n\nWhen I told the others, they laughed at me, so I never spoke with her again. But I miss her. Can you take this letter to her for me? I want to be sure it finds her hands.", objectives = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8901] = { id = 8901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Elenia,", description = "Have you ever known love, young one? It was a thing foreign to me until lately, when I met a girl from the Undercity, Elenia. It is rare enough for one of my kind to look outside our own, let alone one of the Forsaken.\n\nBut now thoughts of her occupy my mind both days and nights.\n\nIf you can, could you take this letter to her? I want her to come here to Mulgore. I hope that she will say yes.", objectives = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8902] = { id = 8902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dearest Elenia,", description = "A lifetime ago, I was betrothed to marry Elenia, my childhood sweetheart. It's been years since I thought about her last, but of late, she frequently occupies my thoughts.\n\nPerhaps, even with everything that has passed, there can be some room in each other's lives for our love.\n\nI'm sure she has changed, also. Can you deliver this letter to her for me? I am too nervous to give it in person.", objectives = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8903] = { id = 8903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's not proper, it's an eyesore, and at worst, it could be a threat to the safety of the Alliance itself.\n\nJust think: what if the guards have been taken in by this strange affliction? Something must be done.\n\nGo to one of the guards here in Stormwind and see if they've been caught up in this foolishness.", objectives = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8904] = { id = 8904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", objectives = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8905] = { id = 8905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8906] = { id = 8906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8907] = { id = 8907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, {name}?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Magister's Bindings to Deliana in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
