quests[8918] = { id = 8918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  That old goblin shall be quite happy with this blood.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance I'd be willing to consider parting with the rest of it.", objectives = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bindings of Elements to Mokvar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8919] = { id = 8919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", objectives = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Dreadmist Bracers to Mokvar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8920] = { id = 8920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", objectives = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bracers of Valor to Mokvar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8921] = { id = 8921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ectoplasmic Distiller", description = "Ah, you're in need of my latest project... the extra-dimensional ghost revealer!  Unfortunately I've run out of funds and manpower.\n\nYou're willing to help?  Excellent!  Our first task is to build a device to harvest the very fabric of death!  Building an ectoplasmic distiller won't be an easy task, {name}.\n\nI'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter.", progress = "I understand the materials are a bit pricey... but I promise you every last one of them shall be necessary!", completion = "These are precisely the materials I needed.  Quite timely too, {name}!\n\nIn mere moments I will have your distiller ready to go!  In the meantime, take this as a reward for aiding me in my project.", objectives = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8922] = { id = 8922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Supernatural Device", description = "I must find a way to speak with Anthion Harmon... or more specifically, his ghost!\n\nI know of an engineer with a queer interest in the supernatural.  He claims he can build a machine that allows him to speak with the dead!\n\nThe blood you collected was intended for him; travel to Gadgetzan and bring it to him as payment for his services!", progress = "You've something for me?", completion = "Excellent!  Just as I was running low!\n\nYou say Deliana sent you?", objectives = "Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8923] = { id = 8923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Supernatural Device", description = "You must be quite brave to have stuck around after that.  That or I've piqued your interest with the piece of armor I gave you.  There is more from where that came from, if you're still interested in aiding me.\n\nThe venom samples you collected are for an acquaintance of mine, Mux Manascrambler, an engineer with an interest in the supernatural.  His latest project consists of a device that allows you to communicate with the dead!  My last hope is to contact Anthion and find out more about my situation.", progress = "You wish to speak to me?", completion = "Excellent!  Just as I was running low!\n\nYou say Mokvar sent you?", objectives = "Take the Sealed Venom Container to Mux Manascrambler in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8924] = { id = 8924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting for Ectoplasm", description = "A fine piece of engineering, if I do say so myself!  You will need to travel a bit, I'm afraid, in order to find the incorporeal undead we require.\n\nYou see, different climates lend different consistencies to the spectral fabric of the dead.  The tortured night elves of Silithus, the spirits of the highborne from Winterspring and the ghosts and banshees of the Eastern Plaguelands should give us the different types of ectoplasm we need.  Be sure to place the distiller nearby before you harvest them!", progress = "Have you gathered the ectoplasm yet, {race}?", completion = "Yes, these will do great!\n\nBy tapping into the otherworldly energies contained within these substances we'll be able to reach out to those whose souls haven't quite left this world yet!", objectives = "Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands. Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8925] = { id = 8925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Portable Power Source", description = "Next we shall need to find a stable and portable source of energy to keep the ectoplasm active.  I've heard rumors of a mighty elemental called Magma Lord Bokk, whose heart is a powerful magma core - an endless supply of heat!\n\nIt's said he can be found in the Burning Steppes, south of Blackrock Mountain.  Bring the magma core to me and we shall have enough juice to power the extra-dimensional ghost revealer!", progress = "Have you found the Magma Lord, {name}?", completion = "You've done it!  This will certainly provide enough energy to power up the extra-dimensional ghost revealer!", objectives = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8926] = { id = 8926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.", objectives = "Bring a Wildheart Belt and a set of Wildheart Gloves Deliana in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8927] = { id = 8927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You've proven to be a very reliable individual, {name}.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", objectives = "Bring a Wildheart Belt and a set of Wildheart Gloves to Mokvar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8928] = { id = 8928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shifty Merchant", description = "The core will provide us with enough juice to power our device; now we just have to build a rod that can channel that energy without melting.\n\nI met an imp in Winterspring that sold all manner of exotic goods.  He had an elemental rod that would do perfectly.  I'm kicking myself in the head right now for not having bought it.\n\nHe lives inside a cave in the entrance to Darkwhisper Gorge.  Sneak in there and try to find him.\n\nMake sure he only charges you forty gold; that's the price he quoted me!", progress = "Have you had any luck finding the imp in Darkwhisper Gorge?", completion = "You did it!   This rod will do perfectly.  Now to put it all together...", objectives = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8929] = { id = 8929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Anthion", description = "Well, nothing left for us to do but try out the goblin's invention.  Word has it that Anthion was mowed down by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and find out whatever Anthion knew.", objectives = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8930] = { id = 8930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Anthion", description = "Very well, {name}.  All that remains is to put the goblin's invention to the test.  Word has it that Anthion was slain by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and see if, indeed, you can speak with the dead!", completion = "Mokvar had you contact me?  I'll do my best to help you, but first I must ask a great favor of you.", objectives = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8931] = { id = 8931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me an ordinary belt and a set of gloves that you wish to upgrade.", objectives = "Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Deliana in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
