quests[8938] = { id = 8938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You've proven to be a very reliable individual, {name}.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", objectives = "Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Mokvar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8939] = { id = 8939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You've proven to be a very reliable individual, {name}.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", objectives = "Bring a Magister's Belt and a set of Magister's Gloves to Mokvar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
