quests[8976] = { id = 8976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8977] = { id = 8977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Deliana", description = "It's been great working with you, {name}.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", objectives = "Bring the Extra-Dimensional Ghost Revealer  to Deliana in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8978] = { id = 8978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Mokvar", description = "It's been great working with you, {name}.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", progress = "You've returned with the device?", completion = "You've returned with the device!  I'm impressed by your dedication, {name}.  Excellent work.", objectives = "Return to Mokvar in Orgrimmar with the Extra-Dimensional Ghost Revealer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8979] = { id = 8979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenstad's Hunch", description = "I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?\n\nOur thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.\n\n I will reimburse you for their purchase when you return.", objectives = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8980] = { id = 8980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinge's Assessment", description = "This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.\n\nIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.", sourceObjective = "Return to Fenstad Argyle outside the bank in the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[8981] = { id = 8981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift Giving" }
quests[8982] = { id = 8982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracing the Source", description = "We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.", sourceObjective = "Speak with Innkeeper Norman in the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[8983] = { id = 8983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracing the Source", description = "Something's wrong with my product? Well, I've never seen so many people wanting something so badly.\n\nI bought my supply from a merchant named Mara Rennick. She's new in town.\n\nShe mentioned she had some goods she had to deliver to the tailor in the Magic Quarter.", sourceObjective = "Speak with Mara Rennick at the tailor's shop in the Undercity's Magic Quarter.", sourceObjectiveStatus = "unverified-source-field" }
quests[8984] = { id = 8984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source Revealed", description = "Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction.\n\nIf he's innocent, then he's got nothing to hide, right?\n\nI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.", sourceObjective = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.", sourceObjectiveStatus = "unverified-source-field" }
quests[8985] = { id = 8985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.You will be able to choose one of these rewards:", objectives = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8986] = { id = 8986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the remains into the brazier.\n\nNow all that is left is to go to the lower portion of Blackrock Spire, to the chamber where War Master Voone resides in Tazz'Alaor, and use the brazier to summon forth the corrupted spirit of my former cohort, Mor Grayhoof. He cannot rest until the amulet piece is taken from him.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", objectives = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8987] = { id = 8987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.You will be able to choose one of these rewards:", objectives = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8988] = { id = 8988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Components of Importance", description = "{class}, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", progress = "Have you returned already then, {class}, with what I sent you out to gather?", completion = "A job well done, {name}. I will imbue the essence of the ashes into the brazier.\n\nNow all that is left is to get into Scholomance, to Ras Frostwhisper's chamber, and use the brazier to summon forth the spirit of my former cohort, Kormok. The amulet piece, and Valthalak's spirit within, has corrupted him even further, and he will not rest until you forcibly take it from him.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", objectives = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8989] = { id = 8989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", progress = "Then it is done? You have retrieved the right piece of Lord Valthalak's amulet, recombined the amulet into one whole, and finally put to rest the spirit of my old companion, Mor Grayhoof?", completion = "Thank you for helping Mor Grayhoof, {name}. Another spirit rests in peace, and we now have the reassembled amulet! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8990] = { id = 8990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8991] = { id = 8991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the right piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.", objectives = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8992] = { id = 8992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Piece of Lord Valthalak's Amulet", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning next.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", progress = "I commend you, {name}, if you have returned with the completed amulet. If not, however, please take care of that as there is no time to waste, I assure you!", completion = "Good work, {name}! Kormok wasn't all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. And now we have the completed amulet! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8993] = { id = 8993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift Giving" }
quests[8994] = { id = 8994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Preparations", description = "We're nearly there, {class}. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.\n\nTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.\n\nGood luck, {name}!", progress = "We've come a long way, {name}, and I just wanted to say that no matter what happens, thank you! You've put yourself in mortal danger to try to help the surviving members of our mercenary company, The Veiled Blade, and as far as I'm concerned, you're one of us now.", completion = "That's it then. I'll extract the metal from the bracers and imbue the brazier with these final components. Then it will be ready for you to summon Lord Valthalak, and finally return his spirit amulet to him.\n\nYou've come quite a distance, {name}, don't falter now that the end is in sight!", objectives = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8995] = { id = 8995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mea Culpa, Lord Valthalak", description = "All is now ready, {name}.\n\nWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.\n\nOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.\n\nGood luck!", progress = "{class}, you dare disturb my rest!", completion = "How fortunate for you that I know you're not part of the original group that stole this from me.\n\nI'll take back what is mine now, mortal! Give the amulet to me!", objectives = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8996] = { id = 8996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Bodley", description = "I will ignore your impertinence this time, {class}, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, {race}, you have shown courage where those that stole from me did not, and probably never could!\n\nReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.", progress = "{name}, you're back and still alive! Well, at least that makes one of us.\n\nYou're going to have to tell me all about it!", completion = "He really said all of that? Wow, I can't believe he's going to call off the spectral assassins and stalkers, even if he did hint at causing my living companions further harm in the future.\n\nThis is a great day, {name}! You've accomplished what few ever could, and absolved us, at least in part, of some of our past sins.\n\nThank you! As a sign of appreciation, I'd like to give you this. You can use it to summon forth spirits at the same haunted locations that you already have, and a few others, too.", objectives = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8997] = { id = 8997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Beginning", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened.", sourceObjective = "Speak with Deliana at The High Seat in Ironforge.", completion = "I am very happy to see you return to me safely, {name}. You look well, if not a bit worse for the wear.\n\nCome, tell me of all that has transpired.", sourceObjectiveStatus = "unverified-source-field" }
quests[8998] = { id = 8998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Beginning", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Mokvar in Orgrimmar and tell him what's happened.", sourceObjective = "Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom.", sourceObjectiveStatus = "unverified-source-field" }
quests[8999] = { id = 8999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", objectives = "Give Deliana your Wildheart Cowl and Wildheart Vest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9000] = { id = 9000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", progress = "As per our deal, are you ready to hand over your Beaststalker's pieces in exchange for your new Beastmaster's Cap and Tunic?", completion = "I'm going to miss you, {name}. I owe you such a debt of gratitude; I think I'll never be able to repay it.\n\nI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come.", objectives = "Give Deliana your Beaststalker's Cap and Beaststalker's Tunic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
