quests[9061] = { id = 9061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptstalker Wristguards", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Wristguards if you bring him the following: 1 Desecrated Wristguards, 6 Wartorn Chain Scraps, 1 Arcanite Bar and 2 Cured Rugged Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9062] = { id = 9062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soaked Pages", description = "Those blasted Wretched sure can run fast at the sight of someone who'll stand up to them.  But let's not worry about that now.  I need to find my instructor's elemental grimoire.\n\nI'm certain I saw one of those cowards throw it into the river but I cannot seem to be able to locate it.  I could use another set of eyes.  I'll throw in a bit of coin if you spot it.", progress = "No luck?  Well, keep looking.  The book is of utmost importance, {class}.", completion = "The book is completely soaked.  Instructor Antheol's not going to like this at all.\n\nHere, take this money.  I have an idea.", objectives = "Apprentice Meledor in Eversong Woods wants you to search the water beneath the bridge nearby and bring him Antheol's Elemental Grimoire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9063] = { id = 9063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torwa Pathfinder", description = "A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.\n\nThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.", objectives = "Speak with Torwa Pathfinder in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9064] = { id = 9064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Fall", description = "Antheol is going to fly off his rocker when he finds out his book is ruined.  I've got a little proposal for you; don't worry, I'll make it worth your while.\n\nTake this book to him and tell him nothing of this incident.  If he asks, just tell him you dropped the book into a puddle.  He has no direct authority over you, so there's not much he can do.\n\nAntheol delivers his lectures at Stillwhisper Pond, southeast of Silvermoon.  You'll do this for us, right?  I'll reward you handsomely for this favor!", progress = "What calls for this interruption to my lecture, {class}?", completion = "You say those two incompetent fools bribed you to lie to me?  You've done very well in coming to me, {name}.", objectives = "Bring Antheol's Elemental Grimoire to Instructor Antheol at Stillwhisper Pond in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9065] = { id = 9065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pattymac Special", objectives = "Make sure you destroy that tower!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9066] = { id = 9066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Discipline", description = "I hope you learn a valuable lesson today, {name}.  Never trust someone else to lie for you.\n\nNow I want you to go back to my two dimwitted students and discipline them using this wand.  My magic tells me that you'll find them along the road to the west on the other side of the Dead Scar.\n\nCome back to me after you've done this.  I'll give you a small reward for your troubles.", progress = "Did you do what I asked of you, {name}?", completion = "Excellent job, {name}.  Don't worry, they're not stuck in that form permanently.  Their apprenticeship, however, won't be restored until they earn it back.", objectives = "Use Antheol's Disciplinary Rod on his two students: Apprentice Ralen and Apprentice Meledor. Return to Antheol at Stillwhisper Pond in Eversong Woods with the rod after this.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9067] = { id = 9067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Party Never Ends", description = "I like to throw parties... just a little something to celebrate the magnificence that is Quel'Thalas!\n\nBut, I'm in a bit of a bind.  I need you to gather up more party supplies.\n\nFrom Vinemaster Suntouched at the Silvermoon City inn, bring me a bottle of Suntouched Special Reserve.  From Zalene Firstlight at Farstrider Retreat acquire more of those delicious Springpaw Appetizers.  And you can pick up my delivery of fireworks from Halis Dawnstrider at Fairbreeze Village.\n\nBe quick about it!", progress = "Didn't I just send you out to gather up more party supplies?  Was that you?  Oh, I can't be expected to remember everyone's face, now can I?  I meet so many... interesting people.\n\nWhat is it that you want?", objectives = "Acquire a bottle of Suntouched Special Reserve, Springpaw Appetizers and a Bundle of Fireworks, and return them to Lord Saltheril at Saltheril's Haven in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9068] = { id = 9068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthshatter Tunic", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make an Earthshatter Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Chain Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
