quests[9113] = { id = 9113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circlet of Faith", description = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed <boy/girl>, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.", objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make a Circlet of Faith if you bring him the following: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth and 3 Nexus Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
