quests[9115] = { id = 9115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandals of Faith", description = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed <boy/girl>, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.", objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make Sandals of Faith if you bring him the following: 1 Desecrated Sandals, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9116] = { id = 9116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gloves of Faith", description = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed <boy/girl>, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.", objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make Gloves of Faith if you bring him the following: 1 Desecrated Gloves, 8 Wartorn Cloth Scraps and 4 Mooncloth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9117] = { id = 9117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belt of Faith", description = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed <boy/girl>, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.", objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make a Belt of Faith if you bring him the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9118] = { id = 9118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindings of Faith", description = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed <boy/girl>, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.", objectives = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make Bindings of Faith if you bring him the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9119] = { id = 9119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfunction at the West Sanctum", description = "Since you're here, {name}, I've a favor to ask you.  Ley-Keeper Velania's apprentice dropped by earlier to ask for assistance.  Apparently there's some malfunction happening at the West Sanctum.  I've been a bit busy entertaining our... most pleasant... dwarven guest.  See if you can give her a hand.  You'll find the West Sanctum southwest of here.", completion = "Look around you.  Things aren't exactly in order.\n\nWe have a severe malfunction at the West Sanctum.  Let us do our best to prevent matters from getting worse.", objectives = "Speak to Ley-Keeper Velania at the West Sanctum in Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9120] = { id = 9120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Kel'Thuzad", description = "The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.\n\nSomeone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?", objectives = "Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9121] = { id = 9121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via arcane cloaking - an old cantrip of the Kirin Tor with a few modifications of my own. Since your dedication to the cause of the Dawn is somewhat lacking, {name}, the price will be high. You may decline and choose to return when you are revered or exalted for a discount.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9122] = { id = 9122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly. Since your dedication to the cause of the Dawn is admirable, we are willing to incur some of those costs.", progress = "None have entered Naxxramas and lived to tell the tale.", completion = "You will feel a slight tingle, {name}. That sensation means it's working. Once complete, you will be able to enter Naxxramas by stepping upon the rune portal in Plaguewood.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 2 Arcane Crystals, 1 Nexus Crystal and 30 gold pieces. You must also be Revered with the Argent Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9123] = { id = 9123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.", completion = "You will feel a slight tingle, {name}. That sensation means it's working. Once complete, you will be able to enter Naxxramas by stepping upon the rune portal in Plaguewood.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9124] = { id = 9124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptstalker Armor Doesn't Make Itself...", description = "How would you like to earn yourself one of these shiny coins?\n\n<Leopold holds up an insignia of the Crusade.>\n\nI've got a little problem that you might be able to help me with, {name}. You see, I make Cryptstalker armor for those daft enough to venture into Naxxramas. While they supply me with the core material requirements for the armor, I always run out of the crypt fiend parts. Bring me back a bundle of parts and I'll pay you with an insignia - usable at the quartermaster.", progress = "How goes the hunt?", completion = "Ah, that'll do nicely, {name}. Remember, I'm always accepting more parts. For every bundle you bring me, I'll reward you with an insignia.", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands wants 30 Crypt Fiend Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9125] = { id = 9125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crypt Fiend Parts", progress = "You did an exemplary job on the first bundle, {name}. If you have more, I will take them now. For every bundle that you turn in, I will reward you with another insignia.", completion = "Most excellent, {name}! These will definitely come to good use." }
quests[9126] = { id = 9126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonescythe Digs", description = "Don Julio's Bonescythe armor pattern requires bone fragments - a lot of bone fragments. While those crazy enough to venture into Naxxramas provide me with enough of the core materials to make the armor, I'm always looking for more Scourge bone fragments.\n\nSo what do you think? Interested in getting your hands dirty and destroying some Scourge at the same time? It's a win-win situation.", progress = "I can direct you to skeleton infested locales, {class}.", completion = "You work fast, {name}. Fast like a fox... Say, have I ever told you about the time I was in a barber shop quartet?\n\nRemind me to tell you that story one of these days.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands wants 30 Bone Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9127] = { id = 9127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone Fragments", progress = "A man in my line of work can never have too many bone fragments, {name}. Whenever you have a surplus of fragments, bring them to me and I'll reward you with another insignia.", completion = "My dream of becoming a full-time dancer at the Gadgetzan disco is soon to become a reality! Keep up the good work, {name}." }
quests[9128] = { id = 9128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elemental Equation", description = "Greetings, adventurer! Are you interested in some work? I pay those under my employ with insignias. These insignias can be used at the Quartermaster to purchase items of power.\n\nAll I need you to do is bring me as many core of elements as you can carry. The more the better!\n\nYou'll find them on elementals of varying shapes and sizes that exist across our world.", progress = "I can only steer you in the right direction, {name}.", completion = "A job well done, {name}! As promised, the insignia is yours. Just remember, there's more where that came from...", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 30 Core of Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9129] = { id = 9129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core of Elements", progress = "Truth be told, I use the cores to create Frostfire armor. It is the armor used by the mages battling in Naxxramas. Without you and others like you, we would most definitely be losing this war.\n\nWith that said, bring me more cores and I shall grant you more insignias.", completion = "You perform a great service for us, {name}. Well done!" }
quests[9130] = { id = 9130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goods from Silvermoon City", description = "Welcome volunteer!  We're running low on supplies here, but Silvermoon has promised us materiel assistance.  That's where you come in.\n\nTake this list over to Skymaster Brightdawn. He'll have further instructions for you on how best to get up to Silvermoon City.", progress = "Yes, what's this?", completion = "Sathiel wants you to head up to Silvermoon City and bring back her goods, huh?  Sure, I can get you there quickly... for a small fee, of course.", objectives = "Deliver Sathiel's Request to Skymaster Brightdawn in Fairbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9131] = { id = 9131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Binding the Dreadnaught", description = "Have you ever seen Dreadnaught armor, {class}? No, of course you haven't. You're still a <boy/girl> - a tyke. Let me tell you, it is glorious.\n\nYou're probably asking yourself what any of this has to do with you, right? I'll tell you what, scrub; I need Dark Iron scraps and I'm willing to pay to get my hands on as many as possible.\n\nI need the scraps to put together sets of Dreadnaught for our champions. Bring me scraps and get paid.", progress = "<Korfax growls at you.>\n\nWhat do you want? Directions? I can provide those...", completion = "This will do, for now. If you get more, you know where to find me.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants 30 Dark Iron Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9132] = { id = 9132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Scraps", progress = "For every armful of the scraps, I'll give you an insignia - the more the better. Now get out of my sight before I split you in two!", completion = "That's all you brought me? Maybe you didn't hear me the first time. I need MORE!" }
quests[9133] = { id = 9133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly to Silvermoon City", description = "{class}, for a very modest amount of coin, I can send you swiftly flying through the air on one of these magnificent beasts.  And, it's safer than walking there, I can assure you!\n\nWhen you arrive in Silvermoon City, seek out Sathren Azuredawn in the Bazaar.\n\nSpeak with me once more when you've decided you're ready to brave the skies.", progress = "That's quite a list you have there, friend.  Let me take a look at it.", completion = "What's this? Sathiel wants all of this!?\n\nDid you bring anyone with you to help take it back?", objectives = "Purchase a flight to Silvermoon City and deliver Sathiel's Request to Sathren Azuredawn in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9134] = { id = 9134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skymistress Gloaming", description = "It doesn't look as if you have a cart or a beast of burden with you, so I'd better send you back only with what you can carry.  If you've spoken with Skymaster Brightdawn at Fairbreeze Village, then you should get this to Sathiel as soon as possible by flying back.\n\nTake these goods for final inspection to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate.", progress = "Wow, that box of goods you have there looks heavy!  You want to load that up on one of my flying beauties?", completion = "Back down to Fairbreeze Village in Eversong Woods, then?  Sure, I can get you there fast!", objectives = "Bring Sathiel's Goods to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9135] = { id = 9135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sathiel", description = "It all checks out as far as I can tell.\n\nSo, the question is, have you already spoken to Skymaster Brightdawn in Fairbreeze Village?  If so, then this can be as simple as you paying the small fare and quickly flying back.\n\nLet me know when you're ready.", progress = "{class}, back so soon?  That doesn't look like everything I requested...", completion = "Well, I guess if he said that the rest of it will be coming quickly overland, then I'll take him at his word.  He's certainly never failed to provide the goods in the past.\n\nThank you, {name}. Here take this coin... it's done nothing but jingle around in my pocket all day.", objectives = "Purchase a flight back to Fairbreeze Village in Eversong Woods and deliver Sathiel's Goods to Sathiel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9136] = { id = 9136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savage Flora", description = "I make a special type of armor for the brave heroes that enter Naxxramas known as Dreamwalker. They are able to provide me with most of the materials I require but I am always looking for those able to retrieve savage fronds from the flora of our world.\n\nYou may think of this job as beneath you, but without the fronds, the armor could not be made.\n\nI am also in a unique position to pay you with an insignia of your choice as both the Dawn and the Crusade supply me with funds.", progress = "I have intimate knowledge of the flora in our world. Do you require direction?", completion = "I am much obliged, {name}.\n\n\n\nPlease remember that I am always accepting fronds.", objectives = "Rayne at Light's Hope Chapel in the Eastern Plaguelands wants 30 Savage Fronds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9137] = { id = 9137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savage Fronds", progress = "For every bundle of fronds that you deliver to me, I will pay you with your choice of an insignia of the Dawn or the Crusade.\n\nInsignias may be turned in to the Quartermaster for various rewards.", completion = "Thank you, {name}. Your work is vital to the success of our campaign against the Scourge." }
quests[9138] = { id = 9138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suncrown Village", description = "We're surrounded here, {class}.  The outlying villages have all been overrun by the Scourge!\n\nYou must head northeast to Suncrown Village immediately and deal with the Nerubian Scourge menace.  You can't miss them - they're spider-like creatures.\n\nThere's no time to waste.... Quel'Thalas must be reclaimed!", completion = "Outstanding! But, there's much to be done before the Scourge menace is completely driven from mighty Quel'Thalas!\n\nHere, take this coin... it's not much, but you've earned it.", objectives = "Slay 10 Nerubis Guards and then return to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9139] = { id = 9139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldenmist Village", description = "We've had one success, but there are two more villages that must be reclaimed!\n\nGoldenmist Village is our next target. It lies to the northwest, and has been taken by the ghosts of the high elves that used to live there. Gruesome, I know, but these are apparently the sorts of tactics that the Scourge like to employ.\n\nGo and defeat these ghosts and wraiths, {class}. Take the west road out of Tranquillien to get there.", completion = "Your success at Goldenmist Village takes us another step closer to taking our land back. Don't fool yourself though, {class}; this fight is far from over.\n\nHere, you've more than earned this. You may need it when you go up against Windrunner Village.", objectives = "Defeat 6 Quel'dorei Ghosts and 4 Quel'dorei Wraiths at Goldenmist Village, and then return to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9140] = { id = 9140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrunner Village", description = "{name}, the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our offensive by thinning out their numbers.\n\nThe magisters at the nearby Sanctum of the Sun have made a special request this time; they want the remains from these Scourge to study in hopes of finding creative ways of fighting them.\n\nGood hunting!", progress = "{class}, has Windrunner Village been liberated? Those damned magisters at the Sanctum of the Sun have been berating me to get their hands on those Scourge remnants I asked you to gather.\n\nDon't worry about that, though. You take your time and get the job done right. I'll deal with the magisters.", completion = "You've done it, {name}. You've broken the Scourge hold on the three villages! Now we can focus our forces with greater ease against the Scourge on the Dead Scar and south at Deatholme.\n\nHere, take your choice of any one of these. I trust that you're not going anywhere? We can really use your continued assistance!", objectives = "Gather 6 Phantasmal Substance and 4 Gargoyle Fragments. Return them to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9141] = { id = 9141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Me \"The Rooster\"", description = "You want a writ? What? Do you expect me to hand you a highly sought after work order just for showing up? I think not, scrub. Crafters from around the world bid for jobs here at the front lines.\n\nIf you want a work order, you'll have to show me that you're willing to bleed for the cause. Bring me a valor token and we'll talk.\n\nAnd there's only one way to get your grubby little scrub mitts on those - get to killin'.", progress = "<Commander Metz chews on his cigar.>\n\nWhat is it? I'm a busy man.", completion = "Alright, here's how it works: For every valor token that you turn in, I'll give you another writ. You complete the order on that writ and deliver the order to Packmaster Stonebruiser. Got it? Good. Now get out of here.", objectives = "Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands wants an Argent Dawn Valor Token.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9142] = { id = 9142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ", progress = "You know the drill, kid. One valor token gets you a craftsman's writ.", completion = "You earned this, scrub. Now, don't cry about your orders. Fill 'em or destroy 'em." }
quests[9143] = { id = 9143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with Zeb'Sora", description = "The lieutenant here rushed us into battle with the trolls across the lake instead of scouting the situation first. We were decimated by his stupidity! You hear me Tomathren? You're an idiot!\n\nWill you help us, {class}? Those trolls still need to be dealt with. I need to stay here and nursemaid him -- I think he's lost his mind.\n\nJust head east to the other side of the lake into Zeb'Sora. I want revenge... bring me their ears so that I can fashion a nice necklace!", progress = "You get those troll ears yet?\n\nYou know, if we could get some help from Tranquillien every once in a while this wouldn't be such a problem. I'm just glad that you're here.", completion = "I appreciate your efforts, {class}! Thank you. Now, we can say that this expedition and all the lives lost on it haven't been in vain.", objectives = "Collect 6 Zeb'Sora Troll Ears and return them to Ranger Valanna in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9144] = { id = 9144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing in the Ghostlands", description = "My nephew was sent into the Ghostlands a few days ago.  He never mentioned anything about his task, except that it was of an extremely secret nature.\n\nHe never returned and I fear for the worst, {class}.  A missing messenger might not mean much to the callous magisters of Silvermoon, but he's like a son to me.  Please, {name}, will you look for him?", completion = "Help me, stranger.  I must... reach Tranquillien... I cannot fail.\n\n<The {race} falls back into unconsciousness as his eyes go blank.>", objectives = "Follow the road out of Fairbreeze Village towards the south and look for Courier Dawnstrider as you approach the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9145] = { id = 9145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Ranger Valanna!", description = "{class}, I can't just sit here waiting for an audience with the high executor or Dame Auriferous! This cannot wait!\n\nWe were dealing with the Shadowpine trolls of Zeb'Sora to the northeast across Lake Elrendar. But the lieutenant mishandled the attack and we lost a lot of Farstriders. Then he just fell to pieces afterward.  Ranger Valanna sent me here, and Ranger Salissa to the Farstrider Enclave for help.\n\nPlease find them, {class}. Valanna was badly injured and the lieutenant's useless.", completion = "Good to hear that Lethvalin made it to safety, and that he was smart enough to ask you for help instead of just waiting there.\n\nI hope that Ranger Salissa made it safely to Farstrider Enclave.", objectives = "Find Ranger Valanna and Lieutenant Tomathren on the shore of Lake Elrendar in the Ghostlands near Suncrown Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[9146] = { id = 9146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Captain Helios", description = "I need one last favor of you, {class}.  Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help.\n\nJust check in with Captain Helios and let him know what's happened here.  I'm sure he'll send help back as soon as he can.", completion = "That's dire news indeed -- I completely overestimated Tomathren's ability to lead.  I'll see to it that a group is dispatched to safely bring him and Valanna back in.\n\nUnfortunately, we never heard from Ranger Salissa, so I fear the worst in her case.\n\nYou've done the Farstriders a great service this day, {class}.  Please take one of these as a small token of our appreciation.", objectives = "Speak with Captain Helios at the Farstrider Enclave on the southern shore of Lake Elrendar in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
